# Problem 1
import itertools

names = ['Peter', 'Eric', 'Alice', 'Arnold']
smoothies = ['watermelon', 'desert', 'cherry', 'dragonfruit']
colors = ['green', 'white', 'red', 'yellow']

def solve():
    for name_perm in itertools.permutations(names):
        # house -> name
        house_name = {i+1: n for i, n in enumerate(name_perm)}
        # constraint 6: Peter loves white
        if house_name[1] != 'Peter':  # because white is house 1 (clue 5)
            continue
        # constraint 2 & 3: cherry in house2, dragonfruit in house4
        # we'll check after smoothie assignment
        for smooth_perm in itertools.permutations(smoothies):
            house_smooth = {i+1: s for i, s in enumerate(smooth_perm)}
            # clue 1 & 3: dragonfruit lover is Eric and in house4
            if house_smooth[4] != 'dragonfruit':
                continue
            if house_name[4] != 'Eric':
                continue
            # clue 2: cherry in house2
            if house_smooth[2] != 'cherry':
                continue
            # clue 4 & 7: Arnold drinks watermelon, and yellow lover drinks watermelon
            if house_name[house_smooth.index('watermelon')+1] != 'Arnold':
                continue
            # clue 7: person who loves yellow is the watermelon lover
            # we'll enforce after colors
            for color_perm in itertools.permutations(colors):
                house_color = {i+1: c for i, c in enumerate(color_perm)}
                # clue 5 & 6: white in house1 and Peter loves white
                if house_color[1] != 'white':
                    continue
                # clue 8: dragonfruit lover's color is red
                if house_color[4] != 'red':
                    continue
                # clue 7: yellow lover is watermelon lover
                # find house of watermelon
                water_house = smooth_perm.index('watermelon') + 1
                if house_color[water_house] != 'yellow':
                    continue
                # all constraints satisfied, print solution
                for h in range(1,5):
                    print(f'House {h}: {house_name[h]}, {house_smooth[h]}, {house_color[h]}')
                return

solve()

# Problem 2
import itertools

names = ['Peter', 'Eric', 'Arnold']
cars = ['toyota camry', 'tesla model 3', 'ford f150']
genres = ['mystery', 'romance', 'science fiction']
jobs = ['doctor', 'teacher', 'engineer']

def solve():
    for name_perm in itertools.permutations(names):
        # Arnold is in house 3
        if name_perm[2] != 'Arnold':
            continue
        house_name = {i+1: n for i, n in enumerate(name_perm)}
        # Eric is the sci‑fi lover (clue 7) – will check after genre assignment
        for genre_perm in itertools.permutations(genres):
            house_genre = {i+1: g for i, g in enumerate(genre_perm)}
            # sci‑fi lover is Eric
            eric_house = [h for h, n in house_name.items() if n == 'Eric'][0]
            if house_genre[eric_house] != 'science fiction':
                continue
            # teacher is directly right of sci‑fi lover (clue 1)
            teacher_house = eric_house + 1
            if teacher_house > 3:
                continue
            # mystery lover is teacher (clue 6)
            if house_genre[teacher_house] != 'mystery':
                continue
            for car_perm in itertools.permutations(cars):
                house_car = {i+1: c for i, c in enumerate(car_perm)}
                # Ford owner is teacher (clue 3)
                if house_car[teacher_house] != 'ford f150':
                    continue
                # engineer is Toyota owner (clue 4)
                # engineer must be right of teacher (clue 5)
                for job_perm in itertools.permutations(jobs):
                    house_job = {i+1: j for i, j in enumerate(job_perm)}
                    # teacher at teacher_house
                    if house_job[teacher_house] != 'teacher':
                        continue
                    # engineer right of teacher
                    engineer_house = [h for h, j in house_job.items() if j == 'engineer'][0]
                    if engineer_house <= teacher_house:
                        continue
                    # engineer's car is Toyota
                    if house_car[engineer_house] != 'toyota camry':
                        continue
                    # all constraints satisfied
                    for h in range(1,4):
                        print(f'House {h}: {house_name[h]}, {house_car[h]}, {house_genre[h]}, {house_job[h]}')
                    return

solve()

# Problem 2
import itertools

names = ['Arnold', 'Eric', 'Peter']
genres = ['romance', 'mystery', 'science fiction']
lunches = ['grilled cheese', 'pizza', 'spaghetti']
smoothies = ['desert', 'watermelon', 'cherry']

def solve():
    for name_perm in itertools.permutations(names):
        # house -> name
        name_at = {i+1: name_perm[i] for i in range(3)}
        # clue 2 & 3
        if name_at[2] != 'Eric' or name_at[1] != 'Peter':
            continue
        for genre_perm in itertools.permutations(genres):
            genre_at = {i+1: genre_perm[i] for i in range(3)}
            # clue 4: Eric loves romance
            if genre_at[2] != 'romance':
                continue
            for lunch_perm in itertools.permutations(lunches):
                lunch_at = {i+1: lunch_perm[i] for i in range(3)}
                # clue 6: Arnold is pizza lover
                arnold_house = [h for h, n in name_at.items() if n == 'Arnold'][0]
                if lunch_at[arnold_house] != 'pizza':
                    continue
                for smooth_perm in itertools.permutations(smoothies):
                    smooth_at = {i+1: smooth_perm[i] for i in range(3)}
                    # clue 5: desert smoothie in house 3
                    if smooth_at[3] != 'desert':
                        continue
                    # clue 1: mystery left of cherry
                    mystery_house = [h for h, g in genre_at.items() if g == 'mystery'][0]
                    cherry_house = [h for h, s in smooth_at.items() if s == 'cherry'][0]
                    if not (mystery_house < cherry_house):
                        continue
                    # clue 7: spaghetti and cherry are adjacent
                    spaghetti_house = [h for h, l in lunch_at.items() if l == 'spaghetti'][0]
                    if abs(spaghetti_house - cherry_house) != 1:
                        continue
                    # all constraints satisfied
                    for h in (1,2,3):
                        print(f"House {h}: {name_at[h]}, {genre_at[h]}, {lunch_at[h]}, {smooth_at[h]}")
                    return

if __name__ == "__main__":
    solve()

