# Problem 4
import itertools, sys

houses = range(1, 7)

names = ['Alice', 'Carol', 'Peter', 'Bob', 'Arnold', 'Eric']
flowers = ['carnations', 'iris', 'tulips', 'daffodils', 'lilies', 'roses']
vacations = ['camping', 'mountain', 'city', 'beach', 'cultural', 'cruise']
styles = ['colonial', 'modern', 'mediterranean', 'craftsman', 'ranch', 'victorian']
heights = ['short', 'very short', 'average', 'tall', 'super tall', 'very tall']
hair = ['red', 'black', 'gray', 'brown', 'auburn', 'blonde']

def house_of(mapping, value):
    for h, v in mapping.items():
        if v == value:
            return h
    return None

def check(state):
    name_at, flower_at, vac_at, style_at, height_at, hair_at = state

    # 1
    if house_of(flower_at, 'lilies') == 5:
        return False
    # 2
    if house_of(height_at, 'very short') != house_of(hair_at, 'auburn'):
        return False
    # 3
    if house_of(name_at, 'Arnold') != house_of(vac_at, 'camping'):
        return False
    # 4
    if house_of(hair_at, 'auburn') != house_of(name_at, 'Eric'):
        return False
    # 5
    if not (house_of(vac_at, 'cultural') < house_of(height_at, 'super tall')):
        return False
    # 6
    if house_of(hair_at, 'gray') and house_of(height_at, 'short'):
        if abs(house_of(hair_at, 'gray') - house_of(height_at, 'short')) != 3:
            return False
    # 7
    if house_of(height_at, 'tall') and house_of(hair_at, 'brown'):
        if not (house_of(height_at, 'tall') < house_of(hair_at, 'brown')):
            return False
    # 8
    if house_of(style_at, 'craftsman') != house_of(name_at, 'Bob'):
        return False
    # 9
    if house_of(height_at, 'very short') and house_of(hair_at, 'blonde'):
        if not (house_of(height_at, 'very short') < house_of(hair_at, 'blonde')):
            return False
    #10
    if house_of(name_at, 'Bob') != house_of(height_at, 'very tall'):
        return False
    #11
    if house_of(flower_at, 'roses') and house_of(name_at, 'Peter'):
        if abs(house_of(flower_at, 'roses') - house_of(name_at, 'Peter')) != 3:
            return False
    #12
    if house_of(style_at, 'modern') == 4:
        return False
    #13
    if house_of(vac_at, 'city') != house_of(height_at, 'short'):
        return False
    #14
    if house_of(style_at, 'colonial') and house_of(flower_at, 'tulips'):
        if not (house_of(style_at, 'colonial') < house_of(flower_at, 'tulips')):
            return False
    #15
    if house_of(flower_at, 'carnations') != house_of(hair_at, 'brown'):
        return False
    #16
    if house_of(hair_at, 'red') != house_of(flower_at, 'lilies'):
        return False
    #17
    if house_of(vac_at, 'mountain') != house_of(style_at, 'victorian'):
        return False
    #18
    if house_of(flower_at, 'daffodils') != house_of(style_at, 'modern'):
        return False
    #19
    if house_of(name_at, 'Arnold') != house_of(height_at, 'average'):
        return False
    #20
    if house_of(style_at, 'mediterranean') == 1:
        return False
    #21
    if house_of(height_at, 'tall') == 5:
        return False
    #22
    if house_of(flower_at, 'tulips') == 4:
        return False
    #23
    if house_of(name_at, 'Carol') != house_of(name_at, 'Bob') - 1:
        return False
    #24
    if house_of(height_at, 'very tall') != house_of(vac_at, 'cultural'):
        return False
    #25
    if house_of(style_at, 'mediterranean') != house_of(hair_at, 'red'):
        return False
    #26
    if house_of(height_at, 'super tall') != house_of(hair_at, 'black'):
        return False
    #27
    if house_of(name_at, 'Eric') != house_of(flower_at, 'roses'):
        return False
    #28
    if house_of(vac_at, 'mountain') and house_of(vac_at, 'cruise'):
        if not (house_of(vac_at, 'mountain') == house_of(vac_at, 'cruise') - 1):
            return False

    return True

def solve():
    name_at = {}
    flower_at = {}
    vac_at = {}
    style_at = {}
    height_at = {}
    hair_at = {}

    rem_name = set(names)
    rem_flower = set(flowers)
    rem_vac = set(vacations)
    rem_style = set(styles)
    rem_height = set(heights)
    rem_hair = set(hair)

    sys.setrecursionlimit(10000)

    def backtrack(pos):
        if pos == 7:
            if check((name_at, flower_at, vac_at, style_at, height_at, hair_at)):
                for h in houses:
                    print(f"House {h}: {name_at[h]}, {flower_at[h]}, {vac_at[h]}, {style_at[h]}, {height_at[h]}, {hair_at[h]}")
                return True
            return False

        for n in list(rem_name):
            name_at[pos] = n
            rem_name.remove(n)
            if not check((name_at, flower_at, vac_at, style_at, height_at, hair_at)):
                rem_name.add(n); del name_at[pos]; continue

            for f in list(rem_flower):
                flower_at[pos] = f
                rem_flower.remove(f)
                if not check((name_at, flower_at, vac_at, style_at, height_at, hair_at)):
                    rem_flower.add(f); del flower_at[pos]; continue

                for v in list(rem_vac):
                    vac_at[pos] = v
                    rem_vac.remove(v)
                    if not check((name_at, flower_at, vac_at, style_at, height_at, hair_at)):
                        rem_vac.add(v); del vac_at[pos]; continue

                    for s in list(rem_style):
                        style_at[pos] = s
                        rem_style.remove(s)
                        if not check((name_at, flower_at, vac_at, style_at, height_at, hair_at)):
                            rem_style.add(s); del style_at[pos]; continue

                        for h in list(rem_height):
                            height_at[pos] = h
                            rem_height.remove(h)
                            if not check((name_at, flower_at, vac_at, style_at, height_at, hair_at)):
                                rem_height.add(h); del height_at[pos]; continue

                            for ha in list(rem_hair):
                                hair_at[pos] = ha
                                rem_hair.remove(ha)
                                if check((name_at, flower_at, vac_at, style_at, height_at, hair_at)):
                                    if backtrack(pos + 1):
                                        return True
                                rem_hair.add(ha); del hair_at[pos]

                            rem_height.add(h); del height_at[pos]

                        rem_style.add(s); del style_at[pos]

                    rem_vac.add(v); del vac_at[pos]

                rem_flower.add(f); del flower_at[pos]

            rem_name.add(n); del name_at[pos]

        return False

    backtrack(1)

if __name__ == "__main__":
    solve()

