# Problem 3
import itertools

names = ['Carol', 'Bob', 'Peter', 'Eric', 'Alice', 'Arnold']
lunches = ['stir fry', 'grilled cheese', 'soup', 'spaghetti', 'stew', 'pizza']
styles = ['colonial', 'victorian', 'craftsman', 'mediterranean', 'ranch', 'modern']

def solve():
    # Fixed placements from clues
    style_fixed = [None] * 6
    style_fixed[4] = 'ranch'          # house 5
    lunch_fixed = [None] * 6
    lunch_fixed[1] = 'grilled cheese'  # house 2

    # Pre‑assign known name‑lunch pairs
    name_to_lunch = {'Alice': 'stew', 'Bob': 'spaghetti'}

    # Helper to get position of a given attribute
    def pos_of(seq, value):
        try:
            return seq.index(value)
        except ValueError:
            return None

    # Backtracking over houses
    def backtrack(idx, name_seq, lunch_seq, style_seq,
                  remaining_names, remaining_lunches, remaining_styles):
        # If all houses are filled, verify all constraints
        if idx == 6:
            # 1. Ranch already placed by construction
            # 2. Modern not in first house
            if style_seq[0] == 'modern':
                return False
            # 3. stir fry left of Peter
            if pos_of(lunch_seq, 'stir fry') != pos_of(name_seq, 'Peter') - 1:
                return False
            # 4. one house between Craftsman and Arnold
            if abs(pos_of(style_seq, 'craftsman') - pos_of(name_seq, 'Arnold')) != 2:
                return False
            # 5. grilled cheese = Victorian
            if style_seq[pos_of(lunch_seq, 'grilled cheese')] != 'victorian':
                return False
            # 6. stew = colonial
            if style_seq[pos_of(lunch_seq, 'stew')] != 'colonial':
                return False
            # 7. soup left of pizza
            if pos_of(lunch_seq, 'soup') != pos_of(lunch_seq, 'pizza') - 1:
                return False
            # 8. Alice loves stew (already enforced via name_to_lunch)
            # 9. two houses between modern and Arnold
            if abs(pos_of(style_seq, 'modern') - pos_of(name_seq, 'Arnold')) != 3:
                return False
            #10. stew not in sixth house
            if pos_of(lunch_seq, 'stew') == 5:
                return False
            #11. spaghetti = Bob (enforced)
            #12. grilled cheese in house 2 (enforced)
            #13. Carol not in house 4
            if name_seq[3] == 'Carol':
                return False
            # All constraints satisfied – print solution
            for h in range(6):
                print(f'House {h+1}: {name_seq[h]}, {lunch_seq[h]}, {style_seq[h]}')
            return True

        # Determine which attributes are already fixed for this house
        fixed_name = None
        fixed_lunch = lunch_fixed[idx]
        fixed_style = style_fixed[idx]

        # Iterate over possible names
        for name in ([fixed_name] if fixed_name else remaining_names):
            if name is None:
                continue
            # Enforce name‑specific lunch constraints early
            required_lunch = name_to_lunch.get(name)
            if required_lunch:
                # If lunch already fixed for this house, it must match
                if fixed_lunch and fixed_lunch != required_lunch:
                    continue
                # If lunch not fixed, we must use this lunch
                if not fixed_lunch and required_lunch not in remaining_lunches:
                    continue

            # Choose a lunch for this house
            possible_lunches = [fixed_lunch] if fixed_lunch else remaining_lunches
            for lunch in possible_lunches:
                # Respect name‑specific lunch
                if required_lunch and lunch != required_lunch:
                    continue
                # Grilled cheese must be in house 2 (already fixed)
                if lunch == 'grilled cheese' and idx != 1:
                    continue
                # Stew not allowed in house 6
                if lunch == 'stew' and idx == 5:
                    continue

                # Choose a style for this house
                possible_styles = [fixed_style] if fixed_style else remaining_styles
                for style in possible_styles:
                    # Enforce style‑lunch links
                    if lunch == 'grilled cheese' and style != 'victorian':
                        continue
                    if lunch == 'stew' and style != 'colonial':
                        continue
                    if style == 'victorian' and lunch != 'grilled cheese':
                        continue
                    if style == 'colonial' and lunch != 'stew':
                        continue
                    # Modern not in first house
                    if idx == 0 and style == 'modern':
                        continue

                    # Prepare next state
                    next_name_seq = name_seq + [name]
                    next_lunch_seq = lunch_seq + [lunch]
                    next_style_seq = style_seq + [style]

                    next_rem_names = [n for n in remaining_names if n != name]
                    next_rem_lunches = [l for l in remaining_lunches if l != lunch]
                    next_rem_styles = [s for s in remaining_styles if s != style]

                    # Early checks that involve already placed houses
                    # 3. stir fry left of Peter (partial)
                    if 'stir fry' in next_lunch_seq and 'Peter' in next_name_seq:
                        if pos_of(next_lunch_seq, 'stir fry') != pos_of(next_name_seq, 'Peter') - 1:
                            continue
                    # 4. distance between Craftsman and Arnold (partial)
                    if 'craftsman' in next_style_seq and 'Arnold' in next_name_seq:
                        if abs(pos_of(next_style_seq, 'craftsman') - pos_of(next_name_seq, 'Arnold')) != 2:
                            continue
                    # 7. soup left of pizza (partial)
                    if 'soup' in next_lunch_seq and 'pizza' in next_lunch_seq:
                        if pos_of(next_lunch_seq, 'soup') != pos_of(next_lunch_seq, 'pizza') - 1:
                            continue
                    # 9. distance between modern and Arnold (partial)
                    if 'modern' in next_style_seq and 'Arnold' in next_name_seq:
                        if abs(pos_of(next_style_seq, 'modern') - pos_of(next_name_seq, 'Arnold')) != 3:
                            continue
                    # 13. Carol not in house 4 (partial)
                    if idx == 3 and name == 'Carol':
                        continue

                    if backtrack(idx+1, next_name_seq, next_lunch_seq, next_style_seq,
                                 next_rem_names, next_rem_lunches, next_rem_styles):
                        return True
        return False

    backtrack(0, [], [], [], names, lunches, styles)

solve()

# Problem 4
import itertools

names = ['Eric', 'Arnold', 'Peter', 'Bob', 'Alice', 'Carol']
musics = ['jazz', 'country', 'pop', 'classical', 'rock', 'hip hop']
styles = ['mediterranean', 'modern', 'colonial', 'ranch', 'victorian', 'craftsman']
sports = ['tennis', 'baseball', 'soccer', 'volleyball', 'swimming', 'basketball']
books = ['science fiction', 'historical fiction', 'mystery', 'biography', 'fantasy', 'romance']

def solve():
    # Fixed assignments from clues
    fixed = {
        'sport': {'Arnold': 'baseball', 'Bob': 'swimming'},
        'music': {'Bob': 'jazz'},
        'style': {'Peter': 'victorian', 'Alice': 'mediterranean'},
        'book': {'Peter': 'fantasy', 'Arnold': 'romance'},
        'sport_house': {3: 'basketball'}   # house 4 (index 3) sport basketball
    }

    # Helper to get position of a name / attribute
    def pos_of(seq, value):
        try:
            return seq.index(value)
        except ValueError:
            return None

    def backtrack(idx, name_seq, music_seq, style_seq, sport_seq, book_seq,
                  rem_names, rem_musics, rem_styles, rem_sports, rem_books):
        if idx == 6:
            # Verify all constraints now that everything is placed
            # 1. baseball -> Arnold (already enforced)
            # 2. Alice left of colonial style
            if not (pos_of(name_seq, 'Alice') < pos_of(style_seq, 'colonial')):
                return False
            # 3. country left of hip hop (adjacent)
            if not (pos_of(music_seq, 'country') == pos_of(music_seq, 'hip hop') - 1):
                return False
            # 4. Peter Victorian (enforced)
            # 5. Peter fantasy book (enforced)
            # 6. baseball person romance book (Arnold already romance)
            # 7. hip hop left of biography
            if not (pos_of(music_seq, 'hip hop') < pos_of(book_seq, 'biography')):
                return False
            # 8. ranch left of romance
            if not (pos_of(style_seq, 'ranch') < pos_of(name_seq, 'Arnold')):
                return False
            # 9. Bob swimming (enforced)
            #10. romance left of mystery
            if not (pos_of(name_seq, 'Arnold') < pos_of(book_seq, 'mystery')):
                return False
            #11. basketball in house 4 (enforced)
            #12. Bob jazz (enforced)
            #13. Craftsman -> mystery book
            if not (book_seq[pos_of(style_seq, 'craftsman')] == 'mystery'):
                return False
            #14. Peter left of basketball
            if not (pos_of(name_seq, 'Peter') < 3):
                return False
            #15. volleyball right of Mediterranean
            if not (pos_of(sport_seq, 'volleyball') > pos_of(style_seq, 'mediterranean')):
                return False
            #16. Mediterranean is Alice (enforced)
            #17. historical fiction left of colonial (adjacent)
            if not (pos_of(book_seq, 'historical fiction') == pos_of(style_seq, 'colonial') - 1):
                return False
            #18. Carol directly left of pop music person
            if not (pos_of(name_seq, 'Carol') == pos_of(music_seq, 'pop') - 1):
