import itertools

names = ["Alice", "Carol", "Eric", "Peter", "Arnold", "Bob"]
cigars = ["pall mall", "yellow monster", "dunhill", "blends", "blue master", "prince"]
smoothies = ["watermelon", "dragonfruit", "lime", "desert", "blueberry", "cherry"]

def idx(lst, value):
    try:
        return lst.index(value)
    except ValueError:
        return None

def check_partial(name, cigar, smoothie):
    # 1. Lime in house 3 (index 2)
    if smoothie[2] != "lime":
        return False

    # 2. Pall Mall = Watermelon smoothie
    pm_idx = cigar.index("pall mall")
    wm_idx = smoothie.index("watermelon")
    if pm_idx != wm_idx:
        return False

    # 3. Desert smoothie lover is Arnold
    des_idx = smoothie.index("desert")
    if name[des_idx] != "Arnold":
        return False

    # 4. Watermelon left of Eric
    wm_idx = smoothie.index("watermelon")
    er_idx = name.index("Eric")
    if wm_idx >= er_idx:
        return False

    # 5. One house between Peter and Carol
    pe_idx = name.index("Peter")
    ca_idx = name.index("Carol")
    if abs(pe_idx - ca_idx) != 2:
        return False

    # 6. Blueberry left of Lime
    bb_idx = smoothie.index("blueberry")
    if bb_idx >= 2:
        return False

    # 7. Watermelon left of Blends smoker
    bl_idx = cigar.index("blends")
    if wm_idx >= bl_idx:
        return False

    # 8. Dragonfruit and Carol adjacent
    dr_idx = smoothie.index("dragonfruit")
    if abs(dr_idx - ca_idx) != 1:
        return False

    # 9. Bob directly left of Carol
    bob_idx = name.index("Bob")
    if bob_idx + 1 != ca_idx:
        return False

    #10. Cherry smoothie = Dunhill smoker
    ch_idx = smoothie.index("cherry")
    du_idx = cigar.index("dunhill")
    if ch_idx != du_idx:
        return False

    #11. Dragonfruit = Prince smoker
    pr_idx = cigar.index("prince")
    if dr_idx != pr_idx:
        return False

    #12. Peter smokes Blue Master
    if cigar[name.index("Peter")] != "blue master":
        return False

    #13. Watermelon and Desert are adjacent
    if abs(wm_idx - des_idx) != 1:
        return False

    return True

def solve():
    for name_perm in itertools.permutations(names):
        for cigar_perm in itertools.permutations(cigars):
            # Peter must smoke Blue Master – early check
            if cigar_perm[name_perm.index("Peter")] != "blue master":
                continue
            for smooth_perm in itertools.permutations(smoothies):
                if check_partial(name_perm, cigar_perm, smooth_perm):
                    for i in range(6):
                        print(f"House {i+1}: {name_perm[i]}, {cigar_perm[i]}, {smooth_perm[i]}")
                    return

solve()

